// Server-only embedded source assets: PDF rendering never fetches company artwork.
import wordmark from "@/assets/companies/admakai-wordmark.png.asset.json";
import inverse from "@/assets/companies/admakai-wordmark-inverse.png.asset.json";

const images: Record<string, string> = {
  [wordmark.url]: "",
  [inverse.url]: "",
};
export function embeddedCompanyImage(url: string): Uint8Array | null {
  const encoded = images[url];
  return encoded ? Uint8Array.from(atob(encoded), c => c.charCodeAt(0)) : null;
}
